CREATE OR REPLACE FUNCTION public.invalidate_voucher_secret() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN UPDATE voucher_items SET secret_valid=false WHERE router_id=OLD.router_id AND source=OLD.source AND name=OLD.name; RETURN OLD; END IF; IF NEW.name IS DISTINCT FROM OLD.name OR NEW.pw_mode IS DISTINCT FROM OLD.pw_mode THEN UPDATE voucher_items SET secret_valid=false WHERE router_id=OLD.router_id AND source=OLD.source AND name=OLD.name; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.claim_voucher_item(rid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i voucher_items; b voucher_batches; BEGIN PERFORM pg_advisory_xact_lock(hashtext(rid::text)); IF EXISTS(SELECT 1 FROM voucher_items WHERE router_id=rid AND state='sent' AND lease_at>now()-interval '2 minutes') THEN RETURN NULL; END IF; SELECT vi.* INTO i FROM voucher_items vi JOIN voucher_batches vb ON vb.id=vi.batch_id JOIN voucher_secrets vs ON vs.item_id=vi.id WHERE vi.router_id=rid AND vb.state='pending' AND vi.secret_valid AND (vi.state='pending' OR (vi.state='sent' AND vi.lease_at<now()-interval '2 minutes')) ORDER BY vb.created_at,vi.ordinal FOR UPDATE OF vi SKIP LOCKED LIMIT 1; IF i.id IS NULL THEN RETURN NULL; END IF; UPDATE voucher_items SET state='sent',lease_at=now() WHERE id=i.id; SELECT * INTO b FROM voucher_batches WHERE id=i.batch_id; RETURN jsonb_build_object('item',to_jsonb(i),'batch',to_jsonb(b)); END $$;
CREATE FUNCTION public.retry_voucher_batch(bid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE voucher_items SET state='pending',lease_at=NULL WHERE batch_id=bid AND state='failed' AND secret_valid; UPDATE voucher_batches SET state='pending' WHERE id=bid; END $$;
REVOKE ALL ON FUNCTION public.retry_voucher_batch(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.retry_voucher_batch(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.purge_voucher_secrets(bid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE voucher_batches SET state='paused' WHERE id=bid; DELETE FROM voucher_secrets WHERE item_id IN (SELECT id FROM voucher_items WHERE batch_id=bid); UPDATE voucher_items SET secret_valid=false WHERE batch_id=bid; END $$;